package dev.exodus.teleporter.domain;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;class ActivationTransactionTest{@Test void secondCompletedDeviceCannotActivate(){ActivationTransaction tx=new ActivationTransaction();assertEquals(ActivationTransaction.Result.ACTIVATED,tx.tryActivate(true,false));assertEquals(ActivationTransaction.Result.REJECTED_SECOND_DEVICE,tx.tryActivate(true,true));assertEquals(ActivationTransaction.Result.INCOMPLETE,tx.tryActivate(false,false));}}
